from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    frames = []
    frame_cells = set()
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
        c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        perimeter = {(r, c) for r in range(r0, r1+1) for c in range(c0, c1+1)
                     if r in (r0, r1) or c in (c0, c1)}
        if all(grid[r][c] == color for r, c in perimeter):
            frames.append((color, r0, r1, c0, c1))
            frame_cells.update(perimeter)
    # Remove the isolated guide pixels and count them by color.
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] and (r, c) not in frame_cells)
    frames.sort(key=lambda f: (f[2]-f[1]-1)*(f[4]-f[3]-1))
    markers = list(counts.items())
    from itertools import permutations
    if len(markers) >= len(frames):
        best = min(permutations(markers, len(frames)),
                   key=lambda assignment: sum(abs(((f[2]-f[1])*(f[4]-f[3])+1)//2-n)
                                              for f, (_, n) in zip(frames, assignment)))
    else:
        best = markers
    # Match each frame to the color whose guide-dot count matches its checkerboard cells.
    for color, r0, r1, c0, c1 in frames:
        for r in range(r0+1, r1):
            for c in range(c0+1, c1):
                out[r][c] = 0
    for frame, (marker, n) in zip(frames, best):
        _, r0, r1, c0, c1 = frame
        cells = [(r, c) for r in range(r0+1, r1) for c in range(c0+1, c1)
                 if (r-r0-1 + c-c0-1) % 2 == 0]
        for r, c in cells:
            out[r][c] = marker
    # Clear all isolated guide pixels from the scene.
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r, c) not in frame_cells:
                out[r][c] = 0
    return out
